const scenes={forest:{name:"나무 길"},field:{name:"들판"},city:{name:"도시"}};
const e=s=>String(s);
export const mascot=(small=false)=>`<svg viewBox="0 0 150 150" role="img" aria-label="탐험 친구 두리"><path d="M31 111C18 87 23 44 49 29c28-18 65-6 76 24 11 30 4 54-19 65-22 11-62 13-75-7Z" fill="#cadf98" stroke="#325640" stroke-width="2"/><path d="M36 72V59c0-47 84-49 84 0v13" fill="none" stroke="#325640" stroke-width="8" stroke-linecap="round"/><rect x="25" y="57" width="20" height="34" rx="9" fill="#f5cd67" stroke="#325640" stroke-width="2"/><rect x="109" y="57" width="20" height="34" rx="9" fill="#f5cd67" stroke="#325640" stroke-width="2"/><ellipse cx="62" cy="76" rx="3" ry="5" fill="#243e35"/><ellipse cx="89" cy="76" rx="3" ry="5" fill="#243e35"/><path d="M69 91q7 7 14 0" stroke="#243e35" fill="none" stroke-width="2.5" stroke-linecap="round"/><ellipse cx="50" cy="86" rx="7" ry="4" fill="#e6aa81"/><ellipse cx="101" cy="86" rx="7" ry="4" fill="#e6aa81"/><path d="M49 119l-4 15m54-16 5 15" stroke="#325640" stroke-width="5" stroke-linecap="round"/></svg>`;
export function landscape(key='forest'){
 const sky=key==='city'?'#e8ebdf':key==='field'?'#e6efe7':'#e6eedc';
 let details='';
 if(key==='forest') details=`<path d="M0 255q110-110 230-20t370-25v210H0Z" fill="#b9cf94"/><path d="M0 325q145-105 325-13t275-10v118H0Z" fill="#91b378"/>${[[55,190,1.05],[175,227,.83],[300,245,.67],[398,242,.57],[482,253,.48],[547,267,.38]].map(([x,y,s])=>`<g transform="translate(${x} ${y}) scale(${s})"><path d="M0 15v100" stroke="#486b48" stroke-width="9" stroke-linecap="round"/><path d="M-48 16c-27-20-15-53 6-63-11-28 13-54 40-52 31-2 54 25 43 52 33 14 36 53 10 67-18 13-79 13-99-4Z" fill="#547e51"/><path d="M-31-28c-9-20 2-43 22-43" stroke="#72965e" fill="none" stroke-width="8" stroke-linecap="round"/></g>`).join('')}<path d="M122 420Q335 310 600 287" stroke="#eddcb3" stroke-width="49" fill="none"/><path d="M126 420Q335 310 600 287" stroke="#f7efd7" stroke-width="2" stroke-dasharray="11 16" fill="none"/>`;
 else if(key==='field') details='<path d="M0 245Q120 200 260 240t340-4v184H0Z" fill="#b9cf94"/><path d="M0 315q160-55 315-3t285-9v117H0Z" fill="#c4c777"/><path d="M0 380q150-50 290 0t310-8v48H0Z" fill="#8eac71"/><path d="M0 340q160-55 340-3M0 360q160-55 340-3M335 268l205 40m-175-52 235 31" fill="none" stroke="#ddd99a" stroke-width="3"/><g stroke="#7d965c" stroke-width="2"><path d="M90 345v-20m-3 10 6-8m38 10v-20m-3 10 6-8m334 37v-20m-3 10 6-8"/></g><path d="M280 420q-10-76 90-120" stroke="#ecdfb9" stroke-width="21" fill="none"/>';
 else details=`<path d="M0 325Q150 290 600 306v114H0Z" fill="#b7c79f"/>${[[35,195,81,144,'#d9b38b'],[135,141,89,194,'#a6b8a1'],[244,207,76,130,'#dfc585'],[342,105,96,232,'#b5c3ac'],[458,175,102,160,'#c0ad92']].map(([x,y,w,h,c])=>`<g><rect x="${x}" y="${y}" width="${w}" height="${h}" rx="6" fill="${c}"/>${Array.from({length:Math.floor(h/32)},(_,r)=>Array.from({length:3},(_,q)=>`<rect x="${x+14+q*23}" y="${y+18+r*30}" width="11" height="14" rx="2" fill="#f4eed4"/>`).join('')).join('')}</g>`).join('')}<path d="M0 363h600v57H0Z" fill="#899a84"/><path d="M0 393h600" stroke="#f4e8c2" stroke-width="3" stroke-dasharray="24 22"/><g transform="translate(419 333)"><rect width="75" height="29" rx="9" fill="#d87454"/><rect x="15" y="-13" width="42" height="24" rx="8" fill="#d87454"/><rect x="20" y="-9" width="32" height="13" rx="4" fill="#e9edd9"/><circle cx="17" cy="29" r="8" fill="#344f40"/><circle cx="60" cy="29" r="8" fill="#344f40"/></g>`;
 return `<svg viewBox="0 0 600 420" preserveAspectRatio="xMidYMid slice" role="img" aria-label="${e(scenes[key].name)} 예시 그림"><rect width="600" height="420" fill="${sky}"/><circle cx="470" cy="87" r="37" fill="#f5cf72"/><path d="M85 105c-18 0-22-22-5-29-1-30 42-36 51-10 23-6 36 27 13 35Z" fill="#fffdf3"/><path d="M305 143c-15 0-19-19-4-25 0-25 34-31 43-8 21-7 33 22 13 30Z" fill="#fffdf3"/>${details}</svg>`;
}
